<?php defined( 'ABSPATH' ) || exit; $checks = ALGQ_Command_Center_Health_Monitor::checks(); $summary = ALGQ_Command_Center_Health_Monitor::summary(); ?>
<div class="wrap algq-command-center algq-admin-shell"><header class="algq-page-header"><div><span class="algq-eyebrow">Platform Operations</span><h1><?php echo esc_html__( 'System Health', 'algq-command-center' ); ?></h1><p><?php echo esc_html( sprintf( __( 'Health score: %d%%', 'algq-command-center' ), $summary['score'] ) ); ?></p></div></header>
<?php if ( isset( $_GET['algq_result'] ) ) : ?><div class="notice notice-<?php echo 'success' === sanitize_key( wp_unslash( $_GET['algq_result'] ) ) ? 'success' : 'warning'; ?> is-dismissible"><p><?php echo esc_html__( 'Command completed.', 'algq-command-center' ); ?></p></div><?php endif; ?>
<section class="algq-panel"><table class="widefat striped"><thead><tr><th>Component</th><th>Status</th><th>Details</th></tr></thead><tbody><?php foreach ( $checks as $check ) : $status = sanitize_key( (string) ( $check['status'] ?? 'warning' ) ); ?><tr><td><strong><?php echo esc_html( (string) $check['label'] ); ?></strong></td><td><span class="algq-status algq-status-<?php echo esc_attr( $status ); ?>"><?php echo esc_html( ucfirst( $status ) ); ?></span></td><td><?php echo esc_html( (string) $check['message'] ); ?></td></tr><?php endforeach; ?></tbody></table></section>
<?php if ( ALGQ_Command_Center_Security::can_run_commands() ) : ?><section class="algq-panel"><h2><?php echo esc_html__( 'Administrative Commands', 'algq-command-center' ); ?></h2><div class="algq-command-grid"><?php foreach ( array( 'run_health_check' => 'Run Health Check', 'refresh_metrics' => 'Refresh Metrics', 'rebuild_pages' => 'Rebuild Missing Pages', 'reconcile_capabilities' => 'Reconcile Capabilities', 'clear_command_center_cache' => 'Clear Command Center Cache' ) as $command => $label ) : ?><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="algq_command_center_command"><input type="hidden" name="command" value="<?php echo esc_attr( $command ); ?>"><?php wp_nonce_field( 'algq_command_center_command' ); ?><button class="button button-secondary" type="submit"><?php echo esc_html( $label ); ?></button></form><?php endforeach; ?></div></section><?php endif; ?></div>
